-- Lumi facts seed: reading, practice, progress, city contexts for en_ru and es_ru.
-- General context gets additional facts (supplement to 000026 seed of 10).
-- Each block is guarded by WHERE NOT EXISTS to prevent duplicates on re-run.

-- ============================================================
-- ENGLISH (en_ru) — READING context
-- ============================================================
INSERT INTO lumi_facts (course_code, context, locale, body)
SELECT 'en_ru', 'reading', 'ru', f.body
FROM (VALUES
    ('Чтение на иностранном языке активирует те же зоны мозга, что и родной — но с чуть большей нагрузкой на префронтальную кору. Со временем разница сглаживается.'),
    ('Технику «чтения по диагонали» (skimming) носители английского осваивают в детстве. Для изучающих язык она появляется позже — примерно после уровня B1.'),
    ('Газеты The Guardian и BBC News пишут на уровне B2–C1. The Sun — примерно B1. New Yorker — C1–C2. Это ориентиры для подбора текстов по уровню.'),
    ('«Graded readers» — адаптированные книги по уровням CEFR — доказали свою эффективность: студенты, читающие их регулярно, расширяют словарный запас вдвое быстрее.'),
    ('Правило «i+1» Стивена Крашена: оптимальный текст для чтения должен быть чуть сложнее вашего текущего уровня — незнакомые слова понятны из контекста.'),
    ('Исследования показывают: достаточно знать 95% слов в тексте, чтобы понимать его без словаря. При 98% — уже комфортное чтение.'),
    ('Английские учебники по чтению делят тексты на «extensive» (много, лёгкое) и «intensive» (мало, детальный разбор). Оба типа нужны — они развивают разные навыки.'),
    ('Подзаголовки в английских статьях называются «subheadings». Они не просто украшение — по ним можно предсказать структуру и заранее включить нужный контекст.'),
    ('Слово «paragraph» пришло из греческого: «para» — рядом, «graphos» — написанное. Изначально это был значок на полях, отмечавший новую мысль.'),
    ('В английских текстах для экзаменов (IELTS, TOEFL) первый абзац почти всегда содержит главную мысль. Этот приём называется «topic sentence» — и он существенно облегчает понимание.'),
    ('Чтение вслух помогает закрепить произношение и интонацию. Дикторы BBC в 1920-х специально обучались «received pronunciation» — эталонному произношению для радиовещания.'),
    ('Коннекторы (however, therefore, nevertheless, although) — скелет английского текста. Умение их распознавать резко улучшает понимание академических и публицистических статей.'),
    ('Художественная проза на английском использует «stream of consciousness» — поток сознания — как у Вирджинии Вулф и Джеймса Джойса. Это усложняет чтение, но отлично тренирует восприятие неформального языка.'),
    ('Английские аббревиатуры в текстах (FYI, ASAP, aka, etc.) — часть письменной нормы. «etc.» от латинского «et cetera» — «и прочее».'),
    ('Метод SQ3R (Survey, Question, Read, Recite, Review) разработан в 1940-х для студентов университетов. Он до сих пор используется в программах подготовки к IELTS и TOEFL.')
) AS f(body)
WHERE NOT EXISTS (
    SELECT 1 FROM lumi_facts WHERE course_code = 'en_ru' AND context = 'reading'
);

-- ============================================================
-- ENGLISH (en_ru) — PRACTICE context
-- ============================================================
INSERT INTO lumi_facts (course_code, context, locale, body)
SELECT 'en_ru', 'practice', 'ru', f.body
FROM (VALUES
    ('Исследование Хебба 1949 года показало: нейроны, которые активируются вместе, укрепляют связи. Каждое повторение слова буквально меняет структуру мозга.'),
    ('Интервальное повторение (spaced repetition) эффективнее зубрёжки в 2–5 раз. Оптимальный момент повторения — прямо перед тем, как вы забудете слово.'),
    ('«Активный словарный запас» — слова, которые вы используете. «Пассивный» — слова, которые вы понимаете. Разрыв между ними обычно 3:1 в пользу пассивного.'),
    ('Shadowing — техника повторения за носителем «тень в тень» — разработана японским полиглотом Александром Аргуэльесом. Она одновременно тренирует произношение, интонацию и грамматику.'),
    ('Ошибки при изучении языка — не провал, а сигнал. Исследования показывают: студенты, которых поправляют сразу, учатся быстрее тех, которых не поправляют вовсе.'),
    ('Феномен «tip of the tongue» (слово «вертится на языке») чаще возникает при стрессе. Именно поэтому практика в расслабленной атмосфере эффективнее экзаменационной зубрёжки.'),
    ('Для запоминания новых слов работает метод «keyword technique»: связать звучание нового слова с уже знакомым и создать образ. Эксперименты показывают прирост запоминания до 40%.'),
    ('Практика письма на английском активирует более глубокую обработку языка, чем чтение. Даже короткий дневник на 3–5 предложений в день ускоряет усвоение грамматики.'),
    ('Диктанты (dictation) — один из старейших методов обучения языку. Современные исследования подтверждают: они эффективно тренируют орфографию, пунктуацию и восприятие на слух одновременно.'),
    ('«Retrieval practice» — вспоминание без подсказки — укрепляет память сильнее, чем перечитывание. Попробуйте закрыть урок и написать всё, что помните.'),
    ('Язык лучше запоминается в эмоциональном контексте. Слова, связанные с яркими событиями или историями, остаются в памяти на годы.'),
    ('Мультизадачность при изучении языка — миф. Мозг не учится параллельно: фоновый английский во время работы почти не усваивается без активного внимания.'),
    ('Говорение с самим собой (self-talk) — легитимная техника. Называйте вслух то, что видите и делаете по-английски. Это снижает барьер перед реальными разговорами.'),
    ('Чтобы слово стало «своим», нужно встретить его в разных контекстах 10–20 раз. Задача практики — создать эти встречи искусственно, если нет языковой среды.'),
    ('Микро-сессии (5–10 минут каждый день) эффективнее редких длинных занятий. Мозг закрепляет знания во сне — важна регулярность, а не продолжительность.')
) AS f(body)
WHERE NOT EXISTS (
    SELECT 1 FROM lumi_facts WHERE course_code = 'en_ru' AND context = 'practice'
);

-- ============================================================
-- ENGLISH (en_ru) — PROGRESS context
-- ============================================================
INSERT INTO lumi_facts (course_code, context, locale, body)
SELECT 'en_ru', 'progress', 'ru', f.body
FROM (VALUES
    ('По оценке FSI (Института иностранной службы США), русскоязычным нужно около 600–750 часов, чтобы достичь рабочего уровня английского (B2). Это примерно 2 года при часе занятий в день.'),
    ('Плато в изучении языка — нормальная фаза, а не провал. Обычно оно наступает между A2 и B1, и между B1 и B2. В это время знания «укладываются» и скоро снова пойдёт рост.'),
    ('Уровень B2 в английском открывает 90% академических статей, большинство фильмов без субтитров и профессиональную переписку. Это порог реальной самостоятельности.'),
    ('Исследования Кена Хайно (Хельсинки, 2009) показали: студенты, которые отслеживали собственный прогресс, осваивали язык на 30% быстрее тех, кто просто учился.'),
    ('Язык не забывается так быстро, как кажется. Даже после долгого перерыва «старые» знания восстанавливаются в 3–5 раз быстрее, чем усваивались впервые.'),
    ('Первая тысяча самых частотных слов английского покрывает около 80% бытовой речи. Вторая тысяча добавляет ещё 10%. После 3000 слов можно читать большинство газет.'),
    ('Уровни CEFR (A1–C2) — не ступеньки лестницы, а зоны. Внутри B1, например, огромный диапазон: начало и конец уровня — это разные люди.'),
    ('Полиглот Като Ломб выучила около 20 языков во взрослом возрасте и утверждала: главное не талант, а время и интерес. Она начала английский в 17 лет по словарю и романам Диккенса.'),
    ('Самый мотивирующий момент в изучении языка — первый раз, когда понимаешь шутку или фильм без перевода. Это «aha-moment» меняет отношение к языку навсегда.'),
    ('Страх говорить — самый частый тормоз прогресса. Психолингвисты называют это «language anxiety» и считают его нормальной реакцией, которая снижается с практикой.'),
    ('Сертификаты (IELTS, TOEFL, Cambridge) — не цель сами по себе, а моментальный снимок уровня. Реальный прогресс — это когда вы думаете на английском, не переводя.'),
    ('Феномен «silent period» — период, когда новый язык понимается, но говорить ещё трудно — нормален и у детей, и у взрослых. Это не регресс: мозг накапливает паттерны.'),
    ('Мотивация бывает внешней (нужен для работы) и внутренней (интересно само по себе). Исследования показывают: внутренняя мотивация коррелирует с более высоким конечным уровнем.'),
    ('Прогресс в языке нелинеен. Бывают недели без видимого роста — а потом внезапный «прорыв», когда всё встаёт на место. Продолжайте практику даже в периоды плато.'),
    ('Чем раньше начать — тем лучше, но «слишком поздно» не бывает. Нейропластичность взрослого мозга ниже, чем у ребёнка, но всё равно достаточна для освоения любого языка.')
) AS f(body)
WHERE NOT EXISTS (
    SELECT 1 FROM lumi_facts WHERE course_code = 'en_ru' AND context = 'progress'
);

-- ============================================================
-- ENGLISH (en_ru) — CITY context
-- ============================================================
INSERT INTO lumi_facts (course_code, context, locale, body)
SELECT 'en_ru', 'city', 'ru', f.body
FROM (VALUES
    ('Лондон в XIX веке был крупнейшим городом мира с населением более 6 миллионов человек. Его рост был настолько стремительным, что архитекторы не успевали за ним — отсюда хаотичная планировка улиц.'),
    ('Нью-Йорк получил прозвище «The Big Apple» в 1920-х — так джазовые музыканты называли главное место для гастролей. Сыграть в Нью-Йорке значило добраться до самого большого яблока.'),
    ('В Лондоне более 170 музеев, большинство из которых бесплатны. Британский музей ежегодно принимает около 6 миллионов посетителей — больше, чем любой другой музей мира.'),
    ('Уличный знак «Mind the Gap» на лондонском метро появился в 1969 году. Он стал настолько культовым, что вдова машиниста попросила оставить запись его голоса на станции Embankment — и Transport for London согласился.'),
    ('В Сан-Франциско кабельные трамваи (cable cars) работают с 1873 года. Это единственный действующий транспорт такого типа в США — охраняется как национальный исторический памятник.'),
    ('Центральный парк Нью-Йорка занимает 341 гектар и был спроектирован в 1858 году. Почти вся его «природа» — искусственная: 18 000 деревьев посажены вручную.'),
    ('В Токио больше звёзд Мишлен, чем в любом другом городе мира. Токийские рестораны в совокупности держат более 200 звёзд — больше, чем Париж и Лондон вместе взятые.'),
    ('Сидней и Мельбурн спорили за столицу Австралии так яростно, что в 1913 году правительство основало Канберру — специально посередине между ними. Оба города проиграли.'),
    ('Дублин назван по-ирландски «Дубх Линн» — «чёрный пруд». Это место слияния рек Лиффи и Подл. Сегодня на этом месте стоит Дублинский замок.'),
    ('Манчестер — родина промышленной революции. Первая в мире железная дорога для пассажиров соединила Манчестер и Ливерпуль в 1830 году.'),
    ('В Нью-Йорке есть подземная станция метро City Hall, закрытая для пассажиров с 1945 года. Но поезда до сих пор проезжают через неё — и это единственный способ её увидеть.'),
    ('Эдинбург проводит крупнейший в мире фестиваль искусств — Edinburgh Fringe, основанный в 1947 году. Каждый август город принимает больше артистов и зрителей, чем жителей.'),
    ('Бостон — один из самых «студенческих» городов мира: здесь более 100 университетов и колледжей на площадь меньше Москвы. MIT и Гарвард находятся буквально через реку друг от друга.'),
    ('В Чикаго находится первый в мире небоскрёб: Home Insurance Building, построенный в 1885 году. Именно здесь изобрели стальной каркас, позволивший строить здания вверх, а не вширь.'),
    ('Сингапур — один из трёх городов-государств в мире (наряду с Ватиканом и Монако) и единственный, где государственным является английский язык, хотя большинство жителей — китайского происхождения.')
) AS f(body)
WHERE NOT EXISTS (
    SELECT 1 FROM lumi_facts WHERE course_code = 'en_ru' AND context = 'city'
);

-- ============================================================
-- ENGLISH (en_ru) — GENERAL supplement (additional to 000026 seed)
-- ============================================================
INSERT INTO lumi_facts (course_code, context, locale, body)
SELECT 'en_ru', 'general', 'ru', f.body
FROM (VALUES
    ('Слово «quiz» появилось в XVIII веке в Дублине — по легенде, хозяин театра поспорил, что за одну ночь введёт в обиход новое слово. К утру оно было написано мелом на всех стенах города.'),
    ('Английский алфавит заимствован из латинского, который пришёл из греческого, который взят у финикийского. Буква «A» изначально была рисунком бычьей головы.'),
    ('В английском языке больше слов, чем в любом другом: Оксфордский словарь насчитывает более 170 000 слов в активном употреблении и ещё 50 000 устаревших.'),
    ('«Podcast» — слово-гибрид из iPod и broadcast. Оно появилось в 2004 году, когда журналист Бен Хаммерсли предложил его в статье для The Guardian.'),
    ('«Maverick» в значении «независимый человек» пришло от имени техасского скотовода Сэмюэла Маверика, который принципиально не клеймил своих коров.'),
    ('Первый словарь английского языка издал Сэмюэл Джонсон в 1755 году. На его создание ушло 9 лет. Джонсон работал в одиночку — пока над Французским словарём трудились 40 академиков.'),
    ('В английском около 200 неправильных глаголов. Это остатки древнеанглийской системы «сильных глаголов» с чередованием гласных, унаследованной от праиндоевропейского.'),
    ('Слово «robot» не английское по происхождению — оно чешское. Карел Чапек придумал его в 1920 году для пьесы R.U.R. от слова «robota» — тяжёлый труд, барщина.'),
    ('«Serendipity» — одно из самых трудных для перевода английских слов: «счастливая случайность». Его придумал Хорас Уолпол в 1754 году по мотивам персидской сказки «Три принца Серендипа».'),
    ('Самое длинное слово в Оксфордском словаре — pneumonoultramicroscopicsilicovolcanoconiosis (45 букв): болезнь лёгких от вулканической пыли. Но его придумали искусственно в 1935 году именно для рекорда.')
) AS f(body)
WHERE NOT EXISTS (
    SELECT 1 FROM lumi_facts WHERE course_code = 'en_ru' AND context = 'general' AND body LIKE '%quiz%'
);

-- ============================================================
-- SPANISH (es_ru) — READING context
-- ============================================================
INSERT INTO lumi_facts (course_code, context, locale, body)
SELECT 'es_ru', 'reading', 'ru', f.body
FROM (VALUES
    ('Испанский — один из немногих языков, где вопросительные и восклицательные знаки ставятся и в начале предложения (¿ и ¡). Это помогает читателю заранее настроиться на тип фразы.'),
    ('«Don Quijote» Сервантеса (1605) — первый современный роман в истории мировой литературы. На испанском он читается на уровне C1–C2 из-за архаичной лексики.'),
    ('Газета El País пишет на уровне B2–C1. Для начинающих подходит Hola! (B1) или детские версии новостей — Elpais.com/ninos.'),
    ('В испанских текстах активно используются уменьшительные суффиксы (-ito, -ita, -illo): они несут не только размер, но и эмоциональный оттенок. «Casita» — не просто маленький дом, а уютный, любимый.'),
    ('Испанские тексты различают два вида «you»: «tú» (неформальное) и «usted» (формальное). В письменных текстах и официальных документах «usted» сокращается до «Ud.» или «Vd.».'),
    ('«Magical realism» — литературный жанр, рождённый в Латинской Америке. Габриэль Гарсиа Маркес, Хорхе Луис Борхес, Исабель Альенде — их тексты отлично тренируют богатую испанскую лексику.'),
    ('Правило DRAE (Diccionario de la Real Academia Española): в испанском почти всегда пишется так, как слышится. Это делает чтение и письмо намного проще, чем в английском.'),
    ('«Subjuntivo» — сослагательное наклонение — встречается в испанских текстах гораздо чаще, чем в русских или английских. Умение его распознавать — ключ к пониманию сложных предложений.'),
    ('Испанские романы и газеты из Испании, Мексики и Аргентины заметно отличаются лексикой. «Coche» в Испании, «carro» в Мексике, «auto» в Аргентине — всё это «автомобиль».'),
    ('«Telenovela» — не только развлечение, но и мощный инструмент для чтения субтитров и понимания разговорного испанского. Сериалы уровня B1–B2 отлично подходят для практики.'),
    ('Испанский использует обратный порядок слов для выражения акцента: «Lo hizo Juan» (это Хуан это сделал) отличается от «Juan lo hizo» (Хуан это сделал). Понимание этого меняет восприятие текстов.'),
    ('«Perífrasis verbales» — глагольные перифразы — частая конструкция в испанских текстах: ir a + infinitivo, estar + gerundio, acabar de + infinitivo. Каждая несёт особый оттенок времени или вида.'),
    ('В испанском официальные документы и юридические тексты написаны сложнее, чем в других языках — «lenguaje jurídico» считается самым консервативным регистром. Но бытовые тексты — одни из самых прозрачных.'),
    ('Аргентинское «vos» (вместо «tú») — отдельная система спряжения, которую используют в Аргентине, Уругвае и части Центральной Америки. Если читаете аргентинские тексты — это объясняет незнакомые формы.'),
    ('Испанские пословицы («refranes») — кладезь идиом и культурного контекста. «No hay mal que por bien no venga» (нет худа без добра) — пример типичной структуры с subjuntivo.')
) AS f(body)
WHERE NOT EXISTS (
    SELECT 1 FROM lumi_facts WHERE course_code = 'es_ru' AND context = 'reading'
);

-- ============================================================
-- SPANISH (es_ru) — PRACTICE context
-- ============================================================
INSERT INTO lumi_facts (course_code, context, locale, body)
SELECT 'es_ru', 'practice', 'ru', f.body
FROM (VALUES
    ('Испанский — один из самых фонетически последовательных языков: написание почти всегда соответствует произношению. Это делает диктанты и практику письма особенно эффективными.'),
    ('Техника «shadowing» особенно хорошо работает с испанским: темп речи носителей выше, чем в русском или английском — тренировка «на скорость» развивает беглость быстрее.'),
    ('«Anki» и другие программы интервального повторения показывают особый эффект при изучении испанских глаголов: их здесь более 12 000, и правила спряжений удобнее учить систематически.'),
    ('Испанский субъюнктив (subjuntivo) — камень преткновения для большинства учеников. Лучший способ его освоить — практика через готовые фразы («ojalá que», «es importante que»), а не через правила.'),
    ('Чтение испанских комиксов (cómics) — эффективная практика: разговорная речь в пузырях, богатая лексика, визуальный контекст. «Mortadelo y Filemón» — классика для уровней A2–B1.'),
    ('Испанские глаголы «ser» и «estar» — одна из главных ловушек. Практика через пары контрастных предложений эффективнее, чем заучивание правил: «Está aburrido» (ему скучно) vs «Es aburrido» (он скучный).'),
    ('Радиостанция «Radio Ambulante» выпускает подкасты с транскриптами на испанском — идеальный материал для практики аудирования и чтения одновременно. Уровень: B1–C1.'),
    ('В испанском около 4000 «cognates» — слов, похожих на английские: «hospital», «animal», «natural», «invisible». Знание английского даёт русскоязычным учащимся дополнительный словарь почти бесплатно.'),
    ('Метод «story method» для запоминания испанских слов: свяжите слово с нелепой историей. «Embarazada» (беременная, а не «в замешательстве») — классическая ловушка, которую забыть невозможно.'),
    ('Практика с носителем раз в неделю даёт больший прирост разговорного испанского, чем ежедневные упражнения в приложении. Реальная коммуникация включает другие механизмы мозга.'),
    ('«Dictogloss» — упражнение: послушать текст дважды, записать ключевые слова, потом восстановить текст своими словами. Одна из самых эффективных техник для грамматики и аудирования.'),
    ('Испанские числительные после 30 пишутся слитно до 99 (treinta y uno), а после 100 — раздельно. Практика с числами в контексте (цены, даты, время) помогает запомнить это без заучивания.'),
    ('«Output hypothesis» Свейна (1985): недостаточно понимать язык — нужно производить его. Именно поэтому пассивное слушание без практики речи и письма даёт меньший прогресс.'),
    ('Испанский «acento» (ударение) важен для смысла: «sí» (да) vs «si» (если), «él» (он) vs «el» (артикль). Практика расстановки ударений улучшает и письмо, и произношение.'),
    ('Испанские фильмы с испанскими субтитрами (не русскими!) — лучший способ соединить аудирование, чтение и словарь в одном упражнении. Начните с «El laberinto del fauno» (B1–B2).')
) AS f(body)
WHERE NOT EXISTS (
    SELECT 1 FROM lumi_facts WHERE course_code = 'es_ru' AND context = 'practice'
);

-- ============================================================
-- SPANISH (es_ru) — PROGRESS context
-- ============================================================
INSERT INTO lumi_facts (course_code, context, locale, body)
SELECT 'es_ru', 'progress', 'ru', f.body
FROM (VALUES
    ('FSI оценивает испанский как один из самых лёгких языков для носителей русского: около 600–750 часов до уровня B2. Это значительно меньше, чем китайский (2200 часов) или арабский.'),
    ('1000 самых частотных слов испанского покрывают около 87% разговорной речи. Если вы знаете их — вы уже понимаете большинство бытовых ситуаций.'),
    ('На уровне B1 по испанскому вы можете путешествовать самостоятельно, читать адаптированные книги и понимать медленную речь носителей. Это достижимо за 300–400 часов практики.'),
    ('«Fossilization» — застывание ошибок — реальный риск при самостоятельном изучении без обратной связи. Именно поэтому важно периодически проверяться: тесты, преподаватель, языковой партнёр.'),
    ('Испанский открывает доступ к литературе 20 стран. Читая по-испански, вы читаете не один язык — вы читаете континент.'),
    ('Первый «настоящий» успех в испанском обычно происходит, когда фраза возникает без перевода в голове — просто появляется. У большинства учеников это происходит около уровня A2–B1.'),
    ('«Interlanguage» — промежуточный язык между родным и изучаемым. Все учащиеся проходят через него: это нормальный этап, а не ошибка в методе.'),
    ('Каждый уровень CEFR требует примерно вдвое больше усилий, чем предыдущий. Переход с B1 на B2 — самый трудоёмкий для большинства взрослых учеников испанского.'),
    ('Жители Испании часто говорят, что испанский латиноамериканцев «чище» — потому что менее подвержен влиянию диалектов. Это спорно, но полезно знать: любой вариант испанского понимают везде.'),
    ('Полиглот Като Ломб учила испанский по романам и словарю в 30+ лет. Её вывод: взрослые учатся эффективнее детей по грамматике и хуже — по произношению.'),
    ('«Language transfer» — бесплатный курс испанского для носителей английского — построен на когнитивном принципе: выводить правила самому, а не запоминать. Подходит для понимания логики языка.'),
    ('Испанский акцент (tilde) — не украшение, а смыслоразличитель. На экзаменах DELE за пропущенные тильды не снимают баллы в устной части, но снимают в письменной.'),
    ('Прогресс в языке часто незаметен изнутри. Записывайте себя на испанском раз в месяц и слушайте прошлые записи — разница за полгода обычно поражает.'),
    ('«Heritage speakers» — люди, выросшие с испанским дома, но учившиеся в другой языковой среде, — часто знают язык лучше, чем думают. Осознание этого — уже прогресс.'),
    ('Освоение испанского облегчает изучение португальского, итальянского и французского. Полиглоты называют это «романским трамплином»: первый язык группы — самый сложный, остальные — быстрее.')
) AS f(body)
WHERE NOT EXISTS (
    SELECT 1 FROM lumi_facts WHERE course_code = 'es_ru' AND context = 'progress'
);

-- ============================================================
-- SPANISH (es_ru) — CITY context
-- ============================================================
INSERT INTO lumi_facts (course_code, context, locale, body)
SELECT 'es_ru', 'city', 'ru', f.body
FROM (VALUES
    ('Мадрид — самая высокая столица Западной Европы: 667 метров над уровнем моря. Из-за этого климат здесь резкий: жаркое лето и холодные зимы, хотя город находится в центре Испании.'),
    ('Буэнос-Айрес называют «Парижем Южной Америки». В начале XX века аргентинская столица была богаче многих европейских городов: её строили итальянские и французские архитекторы.'),
    ('В Барселоне Гауди строил Саграда Фамилия с 1882 года. Строительство продолжается до сих пор — собор планируют достроить к 2026 году, через сто лет после смерти архитектора.'),
    ('Мехико стоит на осушенном озере Тескоко. Именно поэтому город буквально тонет — центральная часть опускается на 10–15 сантиметров в год из-за откачки грунтовых вод.'),
    ('В Боготе (Колумбия) работает одна из крупнейших сетей велодорожек в мире — ciclovía. Каждое воскресенье более 120 километров улиц перекрываются для велосипедистов и пешеходов.'),
    ('Гавана — один из немногих городов мира, где сохранился живой «янтарь» 1950-х: американские автомобили тех лет до сих пор ездят по улицам, потому что после революции 1959 года ввоз новых был запрещён.'),
    ('Севилья — родина фламенко и самый жаркий город Западной Европы. Летом температура регулярно превышает 45°C. Архитектура города адаптирована к жаре: узкие улицы, внутренние дворики (patios), фонтаны.'),
    ('Лима (Перу) — один из крупнейших городов мира, стоящих прямо у океана: 10 миллионов человек живут в пустыне у Тихого океана. Осадков здесь почти не бывает, зато туманы — почти каждое утро.'),
    ('Сантьяго (Чили) — единственная столица Южной Америки, откуда в хорошую погоду видны горы-пятитысячники. Анды возвышаются прямо над городом — и туда можно доехать за час.'),
    ('Монтевидео (Уругвай) — самая южная столица мира после Веллингтона. Это небольшой, спокойный город, который часто называют «самым европейским» в Латинской Америке.'),
    ('Картахена де Индиас (Колумбия) сохранила одну из лучших систем колониальных укреплений в мире. В 1984 году ЮНЕСКО внесло исторический центр в список Всемирного наследия.'),
    ('Валенсия — родина паэльи. Настоящая паэлья валенсиана готовится с кроликом и курицей, а не с морепродуктами. Морская паэлья — позднейшая адаптация для туристов.'),
    ('Сан-Хосе (Коста-Рика) — одна из немногих столиц мира без метро и без крупного аэропорта в черте города. Коста-Рика сознательно ограничивает индустриализацию ради экологии.'),
    ('В Мадриде находится музей Прадо — один из крупнейших художественных музеев мира. Он хранит крупнейшую в мире коллекцию испанской живописи: Гойя, Веласкес, Эль Греко.'),
    ('Кито (Эквадор) стоит прямо на экваторе на высоте 2850 метров — это вторая по высоте столица мира после Ла-Паса. Здесь всегда «вечная весна»: температура редко выходит за пределы 10–20°C.')
) AS f(body)
WHERE NOT EXISTS (
    SELECT 1 FROM lumi_facts WHERE course_code = 'es_ru' AND context = 'city'
);

-- ============================================================
-- SPANISH (es_ru) — GENERAL supplement
-- ============================================================
INSERT INTO lumi_facts (course_code, context, locale, body)
SELECT 'es_ru', 'general', 'ru', f.body
FROM (VALUES
    ('Испанский — официальный язык 21 государства. Это рекорд: ни один другой язык не является официальным в таком количестве стран одновременно.'),
    ('«Ojalá» — одно из самых часто употребляемых испанских слов и один из редких следов арабского влияния в повседневной речи. От «in sha Allah» — «если пожелает Аллах».'),
    ('Язык ацтеков науатль подарил испанскому (а через него — всему миру) слова: chocolate, tomate, aguacate, chile, cacao. Все они пришли в Европу после 1492 года.'),
    ('В испанском языке около 75 000 слов в активном употреблении — значительно меньше, чем в английском. Зато каждое слово в среднем используется чаще.'),
    ('«Tuteo» и «voseo» — два разных способа обращения на «ты» в испанском. «Tú hablas» (Испания, Мексика) vs «vos hablás» (Аргентина, Уругвай). Это не диалект — это отдельная грамматическая норма.'),
    ('Испанский Real Academia Española (RAE) основана в 1713 году и до сих пор является официальным регулятором языка. Её словарь — главный арбитр правописания для всех испаноязычных стран.'),
    ('«Sobremesa» — испанское слово без прямого перевода: время за столом после еды, когда люди просто разговаривают. Это культурная практика, встроенная в язык.'),
    ('В испанском два вида глагола «знать»: «saber» — знать факты и умения, «conocer» — быть знакомым с людьми или местами. Это разграничение отсутствует в русском.'),
    ('Самое длинное слово в испанском — electroencefalografista (27 букв): специалист по электроэнцефалографии. Но в повседневной речи длинные слова встречаются реже, чем в немецком.'),
    ('«Madrugada» — испанское слово для промежутка с полуночи до рассвета. В русском этому нет точного однословного эквивалента — это показывает, как язык отражает культуру.')
) AS f(body)
WHERE NOT EXISTS (
    SELECT 1 FROM lumi_facts WHERE course_code = 'es_ru' AND context = 'general' AND body LIKE '%21 государства%'
);
